// ===================================================================
// قوالب البريد الإلكتروني المصمَّمة (بصائر Theme Studio) — الغلاف المشترك (شعار + شريط أحمر +
// تذييل) في buildBasairEmailShell_، تستخدمه كل رسائل البريد في المشروع بدل كل واحدة قالبها
// الخاص. الخطوط: IBM Plex Sans Arabic (نص) + Readex Pro (عنوان)، نفس زوج خطوط بقية المشروع.
// الشعار مضمَّن base64 مباشرة (بدل معرّف ملف Drive) حتى لا يتعطل لو تحرك/حُذف ملف في Drive.
// ===================================================================

function escapeBasairEmailHtml_(value) {
  return String(value == null ? '' : value).replace(/[&<>"']/g, function (character) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character];
  });
}

// شعار "بصائر" الأبيض الأفقي (basair-theme-studio-v6)، بصيغة base64 — صورة داخلية (cid:basairLogo)
// في كل رسائل المشروع، وليست رابطًا خارجيًا (أكثر موثوقية، ولا يعتمد على بقاء ملف في Drive).
var BASAIR_LOGO_B64_ = '';

function getBasairLogoBlob_() {
  return Utilities.newBlob(Utilities.base64Decode(BASAIR_LOGO_B64_), 'image/png', 'basair-logo.png');
}

// أيقونة واتساب الرسمية (64×64، PNG)، مضمَّنة base64 مباشرة بنفس أسلوب شعار بصائر أعلاه — صورة
// داخلية (cid:whatsappIcon) بدل رابط خارجي، حتى تظهر دائمًا في كل عملاء البريد بلا حجب صور.
var BASAIR_WHATSAPP_ICON_B64_ = '';

function getWhatsAppIconBlob_() {
  return Utilities.newBlob(Utilities.base64Decode(BASAIR_WHATSAPP_ICON_B64_), 'image/png', 'whatsapp-icon.png');
}

// ===================================================================
// الغلاف العام: شعار + شريط أحمر أعلى + عنوان فرعي (kicker) + عنوان رئيسي اختياري + محتوى حر
// (bodyHtml، HTML جاهز يبنيه المستدعي عبر دوال basairEmail* أدناه) + تذييل ثابت. أي بريد جديد
// في المشروع يجب أن يُبنى عبر هذه الدالة، لا بقالب HTML منفصل خاص به.
// ===================================================================
function buildBasairEmailShell_(opts) {
  opts = opts || {};
  var kicker = escapeBasairEmailHtml_(opts.kicker || 'بصائر للعلوم الشرعية');
  var heading = opts.heading ? escapeBasairEmailHtml_(opts.heading) : '';
  var bodyHtml = opts.bodyHtml || '';
  var preheader = escapeBasairEmailHtml_(opts.preheader || '');

  return '<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8">' +
    '<meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&family=Readex+Pro:wght@600;700&display=swap" rel="stylesheet">' +
    '<meta name="color-scheme" content="light"><style>' +
    'html,body{margin:0!important;padding:0!important;width:100%!important;background:#f2f4f5}table{border-spacing:0;border-collapse:collapse}img{display:block;border:0}a{text-decoration:none}' +
    '@media only screen and (max-width:640px){.email-wrap{width:100%!important}.outer-pad{padding:0!important}.header-cell{padding:22px 20px!important}.content-cell{padding:30px 20px 25px!important}.footer-cell{padding:20px!important}.header-note{display:none!important}.login-id{font-size:30px!important;letter-spacing:3px!important}.primary-link{display:block!important;width:auto!important}}' +
    '</style></head><body style="margin:0;padding:0;background-color:#f2f4f5;direction:rtl">' +
    (preheader ? '<div style="display:none!important;overflow:hidden;visibility:hidden;opacity:0;color:transparent;height:0;width:0">' + preheader + '</div>' : '') +
    '<table role="presentation" width="100%" bgcolor="#f2f4f5" style="width:100%;background-color:#f2f4f5"><tr><td class="outer-pad" align="center" style="padding:32px 12px">' +
    '<table class="email-wrap" role="presentation" width="620" style="width:620px;max-width:620px;background-color:#fff;border:1px solid #e1e5e8;border-radius:8px;overflow:hidden">' +
    '<tr><td height="5" bgcolor="#b5262c" style="height:5px;background-color:#b5262c;font-size:0;line-height:0">&nbsp;</td></tr>' +
    '<tr><td class="header-cell" bgcolor="#2f2f2f" style="padding:24px 30px;background-color:#2f2f2f"><table role="presentation" width="100%"><tr>' +
    '<td align="right"><img src="cid:basairLogo" width="148" alt="أكاديمية بصائر" style="width:148px;max-width:148px;height:auto"></td>' +
    '<td class="header-note" align="left" style="color:#d6d6d6;font-family:&quot;IBM Plex Sans Arabic&quot;,&quot;Segoe UI&quot;,Tahoma,Arial,sans-serif;font-size:12px">رسالة خاصة بالحساب</td>' +
    '</tr></table></td></tr>' +
    '<tr><td class="content-cell" bgcolor="#ffffff" style="padding:40px 42px 34px;background-color:#fff;font-family:&quot;IBM Plex Sans Arabic&quot;,&quot;Segoe UI&quot;,Tahoma,Arial,sans-serif;text-align:right">' +
    '<p style="margin:0 0 8px;color:#a51f25;font-size:13px;font-weight:bold">' + kicker + '</p>' +
    (heading ? '<h1 style="margin:0 0 20px;color:#20272d;font-family:&quot;Readex Pro&quot;,&quot;Segoe UI&quot;,Tahoma,Arial,sans-serif;font-size:25px;line-height:1.5">' + heading + '</h1>' : '') +
    bodyHtml +
    '</td></tr>' +
    '<tr><td class="footer-cell" bgcolor="#f8f9fa" style="padding:20px 30px;background-color:#f8f9fa;border-top:1px solid #e8ebed;text-align:center;font-family:&quot;IBM Plex Sans Arabic&quot;,&quot;Segoe UI&quot;,Tahoma,Arial,sans-serif">' +
    '<p style="margin:0 0 6px;color:#4d5963;font-size:12px;font-weight:bold">أكاديمية بصائر للعلوم الشرعية</p><p style="margin:0;color:#929aa1;font-size:11px;line-height:1.8">تأصيل وتحصين · هذه رسالة آلية خاصة بحسابك، فلا تقم بالرد عليها.</p>' +
    '</td></tr></table></td></tr></table></body></html>';
}

// يبني بريد "بصائر" الموحَّد من نص عادي جاهز مسبقًا (كنصوص قوالب "إدارة الرسائل" نفسها المُرسَلة
// أصلًا عبر واتساب، أو أي نص تنبيه بسيط) — بدل بريد نص عادي بلا أي تنسيق. يُهرِّب أي HTML خام
// بالنص ويحوّل الأسطر الجديدة لفواصل <br> صحيحة. طلب المستخدم صراحةً (2026-09-15): كل بريد
// يُرسَل لأي جهة يجب أن يطابق هوية نفس قالب رسالة القبول/رمز التحقق البصرية، لا نص عادي.
function buildBasairPlainMessageEmail_(kicker, heading, plainMsg) {
  var safe = escapeBasairEmailHtml_(plainMsg || '').replace(/\n/g, '<br>');
  return buildBasairEmailShell_({ kicker: kicker, heading: heading, bodyHtml: basairEmailParagraph_(safe) });
}

// ===================================================================
// لبنات محتوى جاهزة (تُستخدم داخل bodyHtml أعلاه) — كل دوال إرسال البريد في المشروع تبني
// محتواها من هذه اللبنات بدل كتابة HTML خامًا من جديد في كل مرة.
// ===================================================================

// text قد يحتوي HTML بسيط (مثل <strong>) عمدًا فلا يُهرَّب — على المستدعي تهريب أي قيمة مستخدم
// متغيرة بنفسه (escapeBasairEmailHtml_) قبل تمريرها هنا لو كانت جزءًا من النص.
function basairEmailParagraph_(text) {
  return '<p style="margin:0 0 14px;color:#4d5963;font-size:15px;line-height:2">' + text + '</p>';
}

function basairEmailHighlightBox_(label, value) {
  return '<table role="presentation" width="100%" bgcolor="#fff7f7" style="width:100%;background-color:#fff7f7;border:1px solid #edcfd1;border-radius:7px"><tr><td align="center" style="padding:22px 14px 20px;text-align:center">' +
    '<p style="margin:0 0 9px;color:#7c5053;font-size:12px;font-weight:bold">' + escapeBasairEmailHtml_(label) + '</p>' +
    '<p class="login-id" dir="ltr" style="margin:0;color:#8d1d22;font-family:Arial,sans-serif;font-size:36px;line-height:1.25;font-weight:700;letter-spacing:6px;white-space:nowrap">' + escapeBasairEmailHtml_(value) + '</p>' +
    '</td></tr></table>';
}

function basairEmailNoticeBox_(text) {
  return '<table role="presentation" width="100%" bgcolor="#f5f7f8" style="width:100%;margin-top:16px;background-color:#f5f7f8;border-radius:7px"><tr>' +
    '<td width="42" valign="top" style="width:42px;padding:14px 14px 14px 0"><span style="width:27px;height:27px;display:inline-block;border-radius:50%;color:#8d1d22;background-color:#f4dcde;font-family:Arial,sans-serif;font-size:15px;line-height:27px;text-align:center;font-weight:bold">!</span></td>' +
    '<td valign="top" style="padding:13px 0 13px 15px;color:#59656f;font-size:13px;line-height:1.9">' + escapeBasairEmailHtml_(text) + '</td>' +
    '</tr></table>';
}

function basairEmailButton_(label, url) {
  return '<table role="presentation" width="100%" style="width:100%;margin-top:24px"><tr><td align="center"><a class="primary-link" href="' + escapeBasairEmailHtml_(url) + '" style="display:inline-block;min-width:190px;padding:13px 22px;border-radius:6px;color:#fff;background-color:#b5262c;font-size:14px;font-weight:bold;text-align:center">' + escapeBasairEmailHtml_(label) + '</a></td></tr></table>';
}

function basairEmailFootnote_(text) {
  return '<p style="margin:23px 0 0;color:#7b858e;font-size:12px;line-height:1.9;text-align:center">' + escapeBasairEmailHtml_(text) + '</p>';
}

// صف بيانات (تسمية + قيمة) داخل basairEmailInfoList_ أدناه — وليس للاستخدام المباشر.
function basairEmailInfoRow_(label, value) {
  return '<tr>' +
    '<td width="130" valign="top" style="width:130px;padding:8px 0;color:#7c5053;font-size:13px;font-weight:bold;white-space:nowrap">' + escapeBasairEmailHtml_(label) + '</td>' +
    '<td valign="top" style="padding:8px 0;color:#20272d;font-size:14px;font-weight:600">' + escapeBasairEmailHtml_(value) + '</td>' +
    '</tr>';
}

// قائمة بيانات صغيرة (تسمية + قيمة لكل صف) — rows: [{label, value}, ...]
function basairEmailInfoList_(rows) {
  var trs = (rows || []).map(function (r) { return basairEmailInfoRow_(r.label, r.value); }).join('');
  return '<table role="presentation" width="100%" bgcolor="#fff7f7" style="width:100%;margin-top:16px;background-color:#fff7f7;border:1px solid #edcfd1;border-radius:7px"><tr><td style="padding:16px 20px">' +
    '<table role="presentation" width="100%">' + trs + '</table></td></tr></table>';
}

// أزرار انضمام لمجموعات واتساب (أخضر بلون العلامة التجارية لواتساب، وليس أحمر بصائر، حتى يتضح
// الفرق عن أزرار الموقع). links: [{label, url}, ...] — بلا اعتماد على أي صورة/أيقونة خارجية
// (تجنّبًا لمشاكل حجب الصور بعملاء البريد)؛ الرمز 💬 نص Unicode عادي يظهر في كل عملاء البريد.
function basairEmailWhatsAppButtons_(links) {
  if (!links || links.length === 0) return '';
  var cells = links.map(function (l) {
    return '<td align="center" style="padding:6px"><a href="' + escapeBasairEmailHtml_(l.url) + '" style="display:inline-block;padding:11px;border-radius:50%;background-color:#25D366;line-height:0"><img src="cid:whatsappIcon" width="34" height="34" alt="واتساب" style="width:34px;height:34px;display:block;border:0"></a></td>';
  }).join('');
  return '<table role="presentation" width="100%" style="width:100%;margin-top:16px"><tr><td align="center"><table role="presentation"><tr>' + cells + '</tr></table></td></tr></table>';
}

// ===================================================================
// 1) إيميل معرّف الدخول (طلاب خارج البحرين، وقت التسجيل) — راجع newStuReg في dataPost.js.
// ===================================================================
function buildBasairLoginIdEmail_(data) {
  var name = escapeBasairEmailHtml_(data.name);
  var loginId = data.loginId;
  var loginUrl = data.loginUrl || 'https://basaerbh.com';

  var body =
    basairEmailParagraph_('أهلًا بك <strong style="color:#20272d">' + name + '</strong>،') +
    basairEmailParagraph_('تم تسجيلك في أكاديمية بصائر للعلوم الشرعية بنظام الدراسة عن بُعد. ولأنك خارج البحرين، أنشأنا لك معرّف دخول خاصًا تستخدمه بدل الرقم الشخصي عند تسجيل الدخول إلى المنصة.') +
    basairEmailHighlightBox_('معرّف الدخول الخاص بك', loginId) +
    basairEmailNoticeBox_('احتفظ بهذا المعرّف في مكان آمن ولا تشاركه مع أي شخص. لن تطلب منك إدارة بصائر إرساله عبر الرسائل أو الهاتف.') +
    basairEmailButton_('تسجيل الدخول إلى المنصة', loginUrl) +
    basairEmailFootnote_('إذا لم تقم بإنشاء هذا الحساب، يرجى تجاهل الرسالة والتواصل مع إدارة الأكاديمية.');

  return buildBasairEmailShell_({
    kicker: 'مرحبًا بك في بصائر',
    heading: 'اكتمل تسجيلك بنجاح',
    bodyHtml: body,
    preheader: 'اكتمل تسجيلك في أكاديمية بصائر، وهذا هو معرّف الدخول الخاص بك.'
  });
}

function sendBasairLoginIdEmail_(email, name, loginId, loginUrl) {
  // كل مُستدعٍ لهذه الدالة يُغلِّفها بـtry/catch أصلًا (فشل إرسال هذا الإيميل تحديدًا لا يُفسد
  // العملية الأصلية) — رمي استثناء هنا بدل تجاهل صامت يجعله يُعامَل بنفس منطق الفشل الموجود
  // مسبقًا بلا أي تعديل إضافي بمواضع الاستدعاء. راجع isEmailBlocked_ بـemailBounces.js.
  if (isEmailBlocked_(email)) {
    throw new Error('البريد الإلكتروني محظور (رُصد فشل تسليم دائم سابق): ' + email);
  }
  var html = buildBasairLoginIdEmail_({ name: name, loginId: loginId, loginUrl: loginUrl || 'https://basaerbh.com' });
  var plainText = 'أهلًا بك ' + name + '\n\nتم تسجيلك بنجاح في أكاديمية بصائر.\nمعرّف الدخول الخاص بك: ' + loginId + '\n\nيرجى حفظه في مكان آمن وعدم مشاركته مع أحد.';

  GmailApp.sendEmail(email, 'معرّف الدخول الخاص بك - أكاديمية بصائر', plainText, {
    name: 'بصائر للعلوم الشرعية',
    htmlBody: html,
    inlineImages: { basairLogo: getBasairLogoBlob_() }
  });
}

// ===================================================================
// 2) إيميل رمز التحقق (تسجيل الدخول / التسجيل الجديد / تغيير البريد) — راجع sendOtpCode_ في
// auth.js، وهو الأكثر إرسالًا في المشروع.
// ===================================================================
function buildBasairOtpEmail_(code, purpose) {
  var isLogin = purpose === 'login';
  var heading = isLogin ? 'رمز تسجيل الدخول' : 'تحقق من بريدك الإلكتروني';
  var intro = isLogin
    ? 'إليك رمز تسجيل الدخول الخاص بك في منصة بصائر:'
    : 'إليك رمز التحقق من بريدك الإلكتروني في منصة بصائر:';

  var body =
    basairEmailParagraph_(intro) +
    basairEmailHighlightBox_('رمز التحقق', code) +
    basairEmailNoticeBox_('هذا الرمز صالح لمدة عشر دقائق فقط. إذا لم تطلب هذا الرمز، يمكنك تجاهل هذه الرسالة بأمان.');

  return buildBasairEmailShell_({
    kicker: 'رمز تحقق',
    heading: heading,
    bodyHtml: body,
    preheader: intro
  });
}

// ===================================================================
// 3) إيميل قبول التسجيل (يُرسَل مرفقًا معه بطاقة الطالب PDF) — راجع acceptedStu_ في oldJS.js،
// الذي يستدعي sendMailWithAttachment_ بالـ HTML الناتج من هذه الدالة كمحتوى الرسالة.
// ===================================================================
// روابط دعوة مجموعات واتساب (الإخوة/الأخوات/الدارسين خارج البحرين — مجموعة واحدة مشتركة بصرف
// النظر عن الجنس، لهذا لا تُقسَّم مثل مجموعتَي الإخوة/الأخوات).
var BASAIR_WHATSAPP_GROUP_MALE_URL_ = 'https://chat.whatsapp.com/FucFU4w4XzkG7Pqvz31ELN?s=cl&p=a&ilr=1';
var BASAIR_WHATSAPP_GROUP_FEMALE_URL_ = 'https://chat.whatsapp.com/FsxXy6Uj1nlCyLrF3z3PZk';
var BASAIR_WHATSAPP_GROUP_REMOTE_URL_ = 'https://chat.whatsapp.com/FZWs5M7uzwV9PAllBjltEG?s=cl&p=a&ilr=1';

// موعد ومكان انطلاق المرحلة الحالية — يُحدَّث يدويًا هنا كلما تغيّر (لا يوجد له عمود بالشيت بعد).
// صيغة التاريخ ثابتة "يوم / شهر / سنة" — basairTermStartDateParts_ يفكّكها لبناء رابط التقويم
// وملف .ics، فمصدر التاريخ الحقيقي واحد فقط (هذا الثابت) ولا يوجد تاريخ ثانٍ منفصل يمكن أن ينحرف عنه.
var BASAIR_TERM_START_DATE_ = '19 / 9 / 2026';
var BASAIR_TERM_START_LOCATION_ = 'جامع عايشة المزعل - سند';
var BASAIR_TERM_START_TITLE_ = 'بداية الدراسة في بصائر';

function basairTermStartDateParts_() {
  var parts = BASAIR_TERM_START_DATE_.split('/').map(function (p) { return p.trim(); });
  return { day: parseInt(parts[0], 10), month: parseInt(parts[1], 10), year: parseInt(parts[2], 10) };
}

// رابط "إضافة سريعة" لتقويم جوجل (بلا مصادقة، فتح مباشر بمتصفح المستلم) — حدث يوم كامل (لا وقت
// محدَّد معروف)، والنهاية باليوم التالي (نهاية غير شاملة، حسب معيار تنسيق تقويم جوجل نفسه).
function buildBasairGoogleCalendarLink_() {
  var d = basairTermStartDateParts_();
  var startDate = new Date(Date.UTC(d.year, d.month - 1, d.day));
  var endDate = new Date(Date.UTC(d.year, d.month - 1, d.day + 1));
  var fmt = function (dt) { return Utilities.formatDate(dt, 'Etc/UTC', 'yyyyMMdd'); };
  var params = {
    action: 'TEMPLATE',
    text: BASAIR_TERM_START_TITLE_,
    dates: fmt(startDate) + '/' + fmt(endDate),
    details: 'بداية الدراسة في أكاديمية بصائر للعلوم الشرعية',
    location: BASAIR_TERM_START_LOCATION_
  };
  var query = Object.keys(params).map(function (k) { return k + '=' + encodeURIComponent(params[k]); }).join('&');
  return 'https://calendar.google.com/calendar/render?' + query;
}

// ملف .ics قياسي (RFC 5545) — يعمل مع أي برنامج تقويم تقريبًا (Outlook، Apple Calendar، إلخ) عند
// فتحه من مرفق الرسالة، بخلاف رابط تقويم جوجل أعلاه الذي يفيد مستخدمي جوجل تحديدًا فقط.
function buildBasairStartEventIcs_(cpr) {
  var d = basairTermStartDateParts_();
  var startDate = new Date(Date.UTC(d.year, d.month - 1, d.day));
  var endDate = new Date(Date.UTC(d.year, d.month - 1, d.day + 1));
  var fmt = function (dt) { return Utilities.formatDate(dt, 'Etc/UTC', 'yyyyMMdd'); };
  var now = Utilities.formatDate(new Date(), 'Etc/UTC', "yyyyMMdd'T'HHmmss'Z'");
  var uid = 'basair-start-' + String(cpr || Utilities.getUuid()).replace(/[^A-Za-z0-9]/g, '') + '-' + fmt(startDate) + '@basaerbh.com';

  var lines = [
    'BEGIN:VCALENDAR',
    'VERSION:2.0',
    'PRODID:-//Basaer Academy//Acceptance Email//AR',
    'CALSCALE:GREGORIAN',
    'METHOD:PUBLISH',
    'BEGIN:VEVENT',
    'UID:' + uid,
    'DTSTAMP:' + now,
    'DTSTART;VALUE=DATE:' + fmt(startDate),
    'DTEND;VALUE=DATE:' + fmt(endDate),
    'SUMMARY:' + BASAIR_TERM_START_TITLE_,
    'LOCATION:' + BASAIR_TERM_START_LOCATION_,
    'DESCRIPTION:بداية الدراسة في أكاديمية بصائر للعلوم الشرعية',
    'END:VEVENT',
    'END:VCALENDAR'
  ];
  return lines.join('\r\n');
}

// gender: 'ذكر' أو 'أنثى'. isRemote: true لطالب "خارج البحرين (دراسة عن بُعد)" (عمود outsideBahrain
// بشيت الطلاب) — له مجموعة واتساب واحدة مشتركة تسبق التقسيم حسب الجنس، لأنها لا تُقسَّم أصلًا.
// أي حالة لا يمكن تحديدها (لا isRemote ولا gender معروف) لا تُظهر أي رابط إطلاقًا (بدل تخمين رابط
// قد لا يخص المستلم).
function buildBasairAcceptanceEmail_(name, gender, isRemote) {
  var whatsappLinks = isRemote ? [{ url: BASAIR_WHATSAPP_GROUP_REMOTE_URL_ }]
    : gender === 'ذكر' ? [{ url: BASAIR_WHATSAPP_GROUP_MALE_URL_ }]
    : gender === 'أنثى' ? [{ url: BASAIR_WHATSAPP_GROUP_FEMALE_URL_ }]
    : [];

  var body =
    basairEmailParagraph_('السلام عليكم ورحمة الله وبركاته') +
    basairEmailParagraph_('يشرفنا انضمام <strong style="color:#20272d">' + escapeBasairEmailHtml_(name) + '</strong> إلى ﴿بصائر﴾ للعلوم الشرعية.') +
    basairEmailParagraph_('هذه الرسالة بمثابة قبول انضمامكم، ونرفق لكم بطاقتكم الإلكترونية والتي ستُستخدم في تسجيل الحضور.') +
    (whatsappLinks.length > 0 ? basairEmailParagraph_('كما نرجو الانضمام إلى مجموعة الواتساب التالية:') + basairEmailWhatsAppButtons_(whatsappLinks) : '') +
    basairEmailInfoList_([
      { label: 'تاريخ البداية', value: BASAIR_TERM_START_DATE_ },
      { label: 'مكان الانطلاق', value: BASAIR_TERM_START_LOCATION_ }
    ]) +
    basairEmailButton_('📅 إضافة الحدث إلى التقويم', buildBasairGoogleCalendarLink_()) +
    basairEmailFootnote_('يمكنك أيضًا إضافة الحدث لأي برنامج تقويم آخر عبر الملف المرفق مع هذه الرسالة.') +
    basairEmailNoticeBox_('نسعد بكم معنا، ونسأل الله لكم التوفيق والسداد في طلب العلم.');

  return buildBasairEmailShell_({
    kicker: 'مرحبًا بك في بصائر',
    heading: 'تم قبول تسجيلك',
    bodyHtml: body,
    preheader: 'تم قبول انضمامك إلى أكاديمية بصائر للعلوم الشرعية.'
  });
}

// ===================================================================
// 4) قالب تهنئة عام (الأعياد والمناسبات) — راجع مثال الاستخدام في dataPost.js (تهنئة عيد الفطر).
// message: نص عادي، كل سطر فيه (\n) يصبح فقرة منفصلة.
// ===================================================================
function buildBasairGreetingEmail_(heading, message) {
  var paragraphs = String(message || '').split('\n')
    .map(function (line) { return line.trim(); })
    .filter(function (line) { return line !== ''; })
    .map(function (line) { return basairEmailParagraph_(escapeBasairEmailHtml_(line)); })
    .join('');

  return buildBasairEmailShell_({
    kicker: 'بصائر للعلوم الشرعية',
    heading: heading,
    bodyHtml: paragraphs
  });
}

// ===================================================================
// 5) إيميل شهادة اجتياز مرحلة — راجع issueStageCertificate في dataPost.js. message: النص المُخصَّص
// (بعد استبدال {name}/{stage}/{link}، عبر resolveCertMessageTemplate_ بdataPost.js) — كل سطر (\n)
// فقرة منفصلة، بنفس أسلوب buildBasairGreetingEmail_ أعلاه، + زر "عرض الشهادة" دائمًا بالنهاية.
// ===================================================================
function buildBasairStageCertEmail_(name, stage, message, certUrl) {
  var paragraphs = String(message || '').split('\n')
    .map(function (line) { return line.trim(); })
    .filter(function (line) { return line !== ''; })
    .map(function (line) { return basairEmailParagraph_(escapeBasairEmailHtml_(line)); })
    .join('');

  var body = paragraphs + basairEmailButton_('عرض الشهادة', certUrl);

  return buildBasairEmailShell_({
    kicker: 'شهادة اجتياز',
    heading: 'تهانينا على اجتياز ' + escapeBasairEmailHtml_(stage || 'المرحلة'),
    bodyHtml: body,
    preheader: 'تم إصدار شهادة اجتياز ' + (stage || 'المرحلة')
  });
}

function sendBasairStageCertEmail_(email, name, message, certUrl, stage) {
  // نفس منطق sendBasairLoginIdEmail_ أعلاه: المُستدعي (dataPost.js) يُغلِّف النداء بـtry/catch
  // ويضبط result.emailSent = false عند أي استثناء — لا حاجة لتعديل منطقه، فقط رمي هنا يكفي.
  if (isEmailBlocked_(email)) {
    throw new Error('البريد الإلكتروني محظور (رُصد فشل تسليم دائم سابق): ' + email);
  }
  var html = buildBasairStageCertEmail_(name, stage, message, certUrl);
  var plainText = String(message || '');

  GmailApp.sendEmail(email, 'شهادة اجتياز ' + (stage || 'المرحلة') + ' - أكاديمية بصائر', plainText, {
    name: 'بصائر للعلوم الشرعية',
    htmlBody: html,
    inlineImages: { basairLogo: getBasairLogoBlob_() }
  });
}
